def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    change_percentage_points = new - old
    change_basis_points = change_percentage_points * 100
    return {
        "value": change_basis_points,
        "trace": {
            "old_yield_2016_percent": old,
            "new_yield_2017_percent": new,
            "change_percentage_points": change_percentage_points,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "basis_points"
            }
        }
    }
